{
  "headline": "FDA's records trace our supply to a plant classified OAI 202 days before the posting",
  "headline_cites": ["E15", "D7"],
  "sentences": [
    {
      "text": "FDA first posted the metronidazole shortage on 2022-01-13 and it has remained on the list for 57 months as of 2026-10-21.",
      "cites": ["E39", "D7"]
    },
    {
      "text": "The Baxter Healthcare Corporation plant at FEI 1416980, which manufactures the product under NDC 00338105548, received an OAI classification on 2026-04-02.",
      "cites": ["E18", "E15"]
    },
    {
      "text": "That OAI inspection ended 202 days before the FDA shortage list update on 2026-10-16.",
      "cites": ["E15", "E36", "D7"]
    },
    {
      "text": "A Warning Letter was subsequently issued to the same plant on 2026-09-29.",
      "cites": ["E16"]
    },
    {
      "text": "A second Baxter plant at FEI 2618677 also appears on the label and has a history of multiple OAI inspections and Warning Letters dating back to 2010.",
      "cites": ["E35", "E21", "E24", "E26", "E28", "E29", "E32", "E33"]
    },
    {
      "text": "The rule-based best option is to buy from Hospira, Inc., which is not on FDA's shortage list today and uses Infomed Fluids Srl (last inspection VAI 2023-04-07).",
      "cites": ["D4"]
    },
    {
      "text": "An approved P&T interchange exists for the same product from Sagent Pharmaceuticals (NDC 25021013182) as of 2026-03-29.",
      "cites": ["D5", "E41"]
    }
  ]
}
